# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/50_party_membership.R
# 50_party_membership.R
# Party membership decline 1930–2022: hollowing out of mass membership parties
#
# Argument (Ch3): parties that once had millions of members rooted in civil
# society became tiny professional organisations disconnected from ordinary
# people. Conservative decline is the cleaner story (2.8m → 172k, -94%).
# Labour complicated by Corbyn surge (2015–16) but long-run trend similar.
# Cross-reference to Ch4: same data speaks to social capital / civic engagement.
#
# Data source: House of Commons Library Research Briefing SN05125,
#   'Membership of political parties in Great Britain', 30 August 2022.
#   Burton M & Tunnicliffe R. Data/figures pp.7–8.
#   Read visually from trend charts; text-confirmed figures noted in comments.
#   data/reports/SN05125.pdf
#
# Caveats (stated in briefing):
#   - Conservative figures pre-1993 likely exaggerated (no central register)
#   - Labour figures pre-1980s also uncertain
#   - Corbyn-era Labour (2015–16) includes affiliated supporters; not comparable
#
# STATUS: First-pass. Data read from charts — re-check against briefing text
#         and Butler & Butler (British Political Facts) before quoting.
#
# OUTPUT:
#   figures/ch3_party_membership.png
#   data/processed/party_membership.csv

pacman::p_load(tidyverse, patchwork)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT

# ============================================================
# 1. DATA — read from HoC Library SN05125 charts (pp.7–8)
# ============================================================
# Text-confirmed values marked with # [text]

conservative <- tibble(
  year       = c(1930, 1935, 1946, 1953, 1960, 1965, 1970, 1975,
                 1980, 1985, 1990, 1994, 2002, 2005, 2008, 2010,
                 2013, 2014, 2018, 2019, 2022),
  membership = c(250, 950, 910, 2800, 2300, 2000, 1400, 1200,    # [text: 910 (1946), 2800 (1953)]
                 1100, 900, 750, 400, 273, 250, 250, 175,         # [text: ~400k mid-1990s; 273 (2002)]
                 134, 150, 124, 180, 172),                         # [text: 134 (2013), 124 (2018), 180 (2019), 172 (2022)]
  party = "Conservative"
)

labour <- tibble(
  year       = c(1930, 1935, 1945, 1953, 1960, 1965, 1970, 1975,
                 1980, 1985, 1990, 1997, 2002, 2005, 2010, 2013,
                 2015, 2016, 2019, 2022),
  membership = c(300, 400, 500, 1000, 800, 750, 700, 650,        # [text: ~1m (1953)]
                 550, 300, 300, 400, 250, 200, 160, 190,          # [text: brief peak ~1997]
                 550, 570, 485, 432),                              # [text: 432 (2022); Corbyn surge]
  party = "Labour"
)

# SNP membership: small until post-indyref surge
# Source: SN05125 p.8 chart; Electoral Commission accounts
snp <- tibble(
  year       = c(2002, 2007, 2010, 2013, 2014, 2015, 2016, 2017, 2019, 2022),
  membership = c(9, 13, 15, 25, 25, 110, 120, 118, 125, 104),   # [text: 104k (2022); surge post-Sep 2014]
  party = "SNP"
)

membership <- bind_rows(conservative, labour, snp)

write_csv(membership, file.path(PROJECT, "data/processed/party_membership.csv"))
cat("Data saved: data/processed/party_membership.csv\n")

# ============================================================
# 2. FIGURE
# ============================================================

col_con <- "#2166ac"
col_lab <- "#d7191c"

p <- ggplot(membership, aes(x = year, y = membership, colour = party)) +
  # Corbyn surge shading
  annotate("rect", xmin = 2014.5, xmax = 2017.5, ymin = -Inf, ymax = Inf,
           fill = "grey90", alpha = 0.6) +
  annotate("text", x = 2016, y = 2600,
           label = "Corbyn\nsurge\n(inc. affiliated\nsupporters)",
           colour = "grey50", size = 2.4, hjust = 0.5, lineheight = 0.85) +
  # Data quality warning region
  annotate("rect", xmin = 1929, xmax = 1993, ymin = -Inf, ymax = Inf,
           fill = "grey95", alpha = 0.5) +
  annotate("text", x = 1931, y = 2600,
           label = "Data quality lower\npre-1993 (estimates)",
           colour = "grey60", size = 2.2, hjust = 0, lineheight = 0.85) +
  geom_line(linewidth = 0.9) +
  geom_point(size = 1.8) +
  # 2014 reference line
  geom_vline(xintercept = 2014, linetype = "dotted",
             colour = "grey40", linewidth = 0.5) +
  annotate("text", x = 2014.3, y = 1800, label = "2014",
           colour = "grey40", size = 2.8, hjust = 0) +
  # Peak labels
  annotate("text", x = 1954.5, y = 2850,
           label = "Con peak:\n2.8m (1953)",
           colour = col_con, size = 2.6, hjust = 0, lineheight = 0.85) +
  annotate("text", x = 1954.5, y = 1050,
           label = "Lab peak:\n~1m (1953)",
           colour = col_lab, size = 2.6, hjust = 0, lineheight = 0.85) +
  # SNP surge annotation
  annotate("text", x = 2014.3, y = 115,
           label = "SNP surge\npost-indyref", colour = "#f4a016",
           size = 2.4, hjust = 0, lineheight = 0.85) +
  # End-point labels
  annotate("text", x = 2023, y = 172,
           label = "172k", colour = col_con, size = 2.6, hjust = 0) +
  annotate("text", x = 2023, y = 432,
           label = "432k", colour = col_lab, size = 2.6, hjust = 0) +
  annotate("text", x = 2023, y = 104,
           label = "104k", colour = "#f4a016", size = 2.6, hjust = 0) +
  scale_colour_manual(values = c("Conservative" = col_con, "Labour" = col_lab,
                               "SNP" = "#f4a016")) +
  scale_x_continuous(breaks = seq(1930, 2020, 10), limits = c(1929, 2027)) +
  scale_y_continuous(limits = c(0, 3000),
                     breaks = seq(0, 3000, 500),
                     labels = function(x) paste0(x, "k")) +
  labs(
    title    = "Mass membership parties have hollowed out: Con and Lab membership, 1930–2022",
    subtitle = paste0(
      "Conservative membership fell from a peak of 2.8 million (1953) to 172,000 (2022) — a 94% decline. ",
      "Labour's long-run decline is front-loaded (1953–1990s), obscured by the Corbyn surge (2015–16). ",
      "SNP surge post-2014 indyref reflects nationalist mobilisation, not mass party revival."
    ),
    x = NULL, y = "Members (thousands)", colour = NULL,
    caption  = paste0(
      "Source: House of Commons Library Research Briefing SN05125 (Burton & Tunnicliffe, 2022). ",
      "Data from Butler & Butler (British Political Facts), Electoral Commission accounts, party HQs.\n",
      "Conservative figures pre-1993 likely exaggerated; Labour pre-1980 also uncertain. ",
      "2015–16 Labour figures include affiliated supporters — not directly comparable.\n",
      "STATUS: first-pass — data read from charts; re-check against text before quoting."
    )
  ) +
  theme_minimal(base_size = 11) +
  theme(
    panel.grid.minor = element_blank(),
    plot.title       = element_text(face = "bold", size = 11),
    plot.subtitle    = element_text(colour = "grey30", size = 8.5),
    plot.caption     = element_text(colour = "grey50", size = 7),
    axis.text.x      = element_text(angle = 45, hjust = 1),
    legend.position  = "bottom"
  )

ggsave(file.path(PROJECT, "figures/ch3_party_membership.png"),
       p, width = 12, height = 6, dpi = 300)

cat("Figure saved: figures/ch3_party_membership.png\n")

# ============================================================
# 3. KEY NUMBERS
# ============================================================

cat("\n--- Key numbers for Ch3 text ---\n")
con_peak <- conservative$membership[conservative$year == 1953]
con_end  <- conservative$membership[conservative$year == 2022]
lab_peak <- labour$membership[labour$year == 1953]
lab_end  <- labour$membership[labour$year == 2022]

cat(sprintf("Conservative: peak %dk (1953) → %dk (2022) = %.0f%% decline\n",
            con_peak, con_end, (1 - con_end/con_peak)*100))
cat(sprintf("Labour: peak %dk (1953) → %dk (2022) = %.0f%% decline\n",
            lab_peak, lab_end, (1 - lab_end/lab_peak)*100))
cat(sprintf("Combined peak (1953): %dk\n", con_peak + lab_peak))
cat(sprintf("Combined (2022): %dk\n", con_end + lab_end))
cat(sprintf("Combined decline: %.0f%%\n", (1 - (con_end+lab_end)/(con_peak+lab_peak))*100))
cat("\nDone.\n")
